      "max": 5.0,
      "feedback": "string"
    },
    "instructional_alignment": {
      "score": 0.0,
      "max": 4.0,
      "feedback": "string"
    },
    "technical_ergonomics": {
      "score": 0.0,
      "max": 2.0,
      "feedback": "string"
